import { MeshBasicNodeMaterial, PlaneGeometry, Group, Mesh, Color, DoubleSide } from 'three/webgpu';
import { uv, vec2, vec3, mix, time, fract, sin, dot, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, SRGBColorSpace } = ctx.THREE;
  const group = new Group();

  const colors =
    config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const v3 = (c) => vec3(c.r, c.g, c.b);
  const inkN = v3(ink);
  const paperN = v3(paper);
  const accentN = v3(accent);
  const surfaceN = v3(surface);

  const imageUrl =
    config.imageUrl ?? config.intent?.visualSpec?.imageUrl ?? null;

  // ---- card dimensions (aspect matches 512x320 atlas) ----
  const cardW = 1.6;
  const cardH = 1.0;

  // ---- frame (slightly larger, sits behind) ----
  const frameGeo = new PlaneGeometry(cardW + 0.03, cardH + 0.03);
  const frameMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  frameMat.colorNode = inkN.lerp(paperN, 0.06);
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.003);
  group.add(frame);

  // ---- card surface ----
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const mat = new MeshBasicNodeMaterial({ side: DoubleSide });

  const uvNode = uv();
  // engineered vertical gradient: surface (bottom) -> ink (top)
  const grad = mix(surfaceN, inkN, uvNode.y.oneMinus());
  // subtle horizontal engineered banding for machined feel
  const band = sin(uvNode.x.mul(14.0)).mul(0.015);
  // hash grain
  const grainSeed = dot(uvNode.mul(vec2(512.0, 320.0)), vec2(0.019, 0.027));
  const grain = fract(sin(grainSeed).add(time.mul(0.6)).mul(43758.5453)).sub(0.5);

  // initial colorNode (pre-texture): gradient + band + grain
  mat.colorNode = grad.add(band).add(grain.mul(0.03));

  const card = new Mesh(cardGeo, mat);
  card.position.set(0, 0, 0);
  group.add(card);

  // ---- accent edge strip (left) ----
  const edgeGeo = new PlaneGeometry(0.03, cardH);
  const edgeMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  edgeMat.colorNode = accentN;
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(-cardW / 2 + 0.016, 0, 0.0015);
  group.add(edge);

  // ---- thin top hairline (paper-tinted) ----
  const hairGeo = new PlaneGeometry(cardW, 0.012);
  const hairMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  hairMat.colorNode = inkN.lerp(paperN, 0.22);
  const hair = new Mesh(hairGeo, hairMat);
  hair.position.set(0, cardH / 2 - 0.008, 0.0015);
  group.add(hair);

  // ---- accent corner pip (foreground depth accent) ----
  const pipGeo = new PlaneGeometry(0.07, 0.07);
  const pipMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  pipMat.colorNode = accentN;
  const pip = new Mesh(pipGeo, pipMat);
  pip.position.set(cardW / 2 - 0.09, -cardH / 2 + 0.09, 0.002);
  pip.scale.set(0.0001, 0.0001, 1);
  group.add(pip);

  // ---- async texture load -> swap colorNode to include brushed metal ----
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      const texNode = texture(tex, uvNode);
      // engineered surface: blend metal map with gradient, keep band + grain
      const mixed = mix(texNode, grad, 0.32);
      mat.colorNode = mixed.add(band).add(grain.mul(0.035));
      mat.needsUpdate = true;
    });
  }

  // ---- entrance motion (weighted-settle) ----
  const timelines = [];
  const tl = gsap.timeline();
  tl.from(card.position, { z: -0.35, duration: 0.7, ease: 'power3.out' }, 0);
  tl.from(card.scale, { x: 0.9, y: 0.9, duration: 0.7, ease: 'power3.out' }, 0);
  tl.from(frame.material, { opacity: 0, duration: 0.6, ease: 'power2.out' }, 0);
  frame.material.transparent = true;
  tl.to(
    card.scale,
    { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' },
    0.65
  );
  tl.to(
    pip.scale,
    { x: 1.0, y: 1.0, duration: 0.5, ease: 'back.out(2.2)' },
    0.55
  );
  timelines.push(tl);

  // ---- handlers (none — static composition) ----
  group.userData.handlers = {};

  // ---- cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    cardGeo.dispose();
    frameGeo.dispose();
    edgeGeo.dispose();
    hairGeo.dispose();
    pipGeo.dispose();
    mat.dispose();
    frameMat.dispose();
    edgeMat.dispose();
    hairMat.dispose();
    pipMat.dispose();
  };

  return group;
}
